import { useCallback, useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const REFRESH_INTERVAL_MS = 10_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    typeof candidate.unit === "string"
  );
}

function isMetricArray(value: unknown): value is Metric[] {
  return Array.isArray(value) && value.every(isMetric);
}

function formatSecondsAgo(seconds: number): string {
  if (seconds <= 1) return "just now";
  return `${seconds} seconds ago`;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [, setTick] = useState(0);

  const previousValuesRef = useRef<Map<string, number>>(new Map());
  const inFlightRef = useRef<AbortController | null>(null);

  const fetchMetrics = useCallback(async () => {
    inFlightRef.current?.abort();
    const controller = new AbortController();
    inFlightRef.current = controller;

    try {
      const response = await fetch("/api/metrics", { signal: controller.signal });
      if (!response.ok) {
        throw new Error(`Request failed with status ${response.status}`);
      }
      const data: unknown = await response.json();
      if (!isMetricArray(data)) {
        throw new Error("Unexpected response shape from /api/metrics");
      }

      if (controller.signal.aborted) return;

      const previousValues = previousValuesRef.current;
      const nextChanged = new Set<string>();
      const nextValues = new Map<string, number>();

      for (const metric of data) {
        nextValues.set(metric.name, metric.value);
        const previousValue = previousValues.get(metric.name);
        if (previousValue !== undefined && previousValue !== metric.value) {
          nextChanged.add(metric.name);
        }
      }

      previousValuesRef.current = nextValues;
      setMetrics(data);
      setChangedNames(nextChanged);
      setLastUpdated(new Date());
      setError(null);
    } catch (err) {
      if (err instanceof DOMException && err.name === "AbortError") return;
      setError(err instanceof Error ? err.message : "Failed to load metrics");
    } finally {
      if (inFlightRef.current === controller) {
        inFlightRef.current = null;
      }
    }
  }, []);

  useEffect(() => {
    fetchMetrics();

    let intervalId: ReturnType<typeof setInterval> | null = null;

    const startPolling = () => {
      if (intervalId === null) {
        intervalId = setInterval(fetchMetrics, REFRESH_INTERVAL_MS);
      }
    };

    const stopPolling = () => {
      if (intervalId !== null) {
        clearInterval(intervalId);
        intervalId = null;
      }
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        fetchMetrics();
        startPolling();
      }
    };

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      stopPolling();
      inFlightRef.current?.abort();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [fetchMetrics]);

  // Re-render once a second so the "seconds ago" label stays live; the value
  // itself is computed below from lastUpdated + the current time, not stored.
  useEffect(() => {
    const tickId = setInterval(() => setTick((t) => t + 1), 1000);
    return () => clearInterval(tickId);
  }, []);

  const secondsAgo = lastUpdated
    ? Math.floor((Date.now() - lastUpdated.getTime()) / 1000)
    : 0;

  return (
    <div className="metrics-panel">
      <div className="metrics-panel-header">
        <h2>Metrics</h2>
        {lastUpdated && (
          <span className="metrics-panel-updated">
            Last updated {formatSecondsAgo(secondsAgo)}
          </span>
        )}
      </div>

      {error && <div className="metrics-panel-error">{error}</div>}

      <ul className="metrics-panel-list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? "metrics-panel-item metrics-panel-item-changed"
                : "metrics-panel-item"
            }
          >
            <span className="metrics-panel-item-name">{metric.name}</span>
            <span className="metrics-panel-item-value">
              {metric.value}
              {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}
